import{_ as t,a as i,b as r,c as n,d as l,e as d,f as s,g as c,h as o,i as a,j as p,k as h,l as m}from"./chunks/ADB8.B4evyQaN.js";import{_ as u,o as b,c as g,a3 as w}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Android Debug Bridge","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/ADB.md","filePath":"troubleshoot/ADB.md"}'),_={name:"troubleshoot/ADB.md"};function f(y,e,D,v,A,k){return b(),g("div",null,[...e[0]||(e[0]=[w('<h3 id="prepare-your-device-for-debug" tabindex="-1">Prepare your device for Debug <a class="header-anchor" href="#prepare-your-device-for-debug" aria-label="Permalink to &quot;Prepare your device for Debug&quot;">​</a></h3><p>This step is mandatory to connect it through ADB with a physical connection. If your device doesn&#39;t have a physical USB connector you need to use ADB over Wi-Fi (documentation pending).</p><p>If you want to debug a smartphone skip to <a href="#smartphone">here</a>.</p><h4 id="smartwatch" tabindex="-1">Smartwatch <a class="header-anchor" href="#smartwatch" aria-label="Permalink to &quot;Smartwatch&quot;">​</a></h4><ol><li>Enable Developer Options<br> Settings -&gt; About -&gt; Versions -&gt; Build Number<br> Tap 7 times on the build number version until the watch displays &quot;you&#39;re a developer&quot;.<br><img src="'+t+'" style="zoom:75%;"></li><li>Settings -&gt; Developer Options -&gt; ADB Debugging<br> Enable ADB Debugging<br><img src="'+i+'" style="zoom:75%;"></li></ol><h4 id="smartphone" tabindex="-1">Smartphone <a class="header-anchor" href="#smartphone" aria-label="Permalink to &quot;Smartphone&quot;">​</a></h4><ol><li>Enable Developer Options<br> Settings -&gt; About -&gt; Software -&gt; Build Number<br> Tap 7 times on the build number version until the phone displays &quot;you&#39;re a developer&quot;.<br><img src="'+r+'" style="zoom:75%;"></li><li>Settings -&gt; Developer Options -&gt; USB Debugging<br> Enable ADB Debugging<br><img src="'+n+'" style="zoom:75%;"></li></ol><h3 id="install-adb-on-a-windows-computer" tabindex="-1">Install ADB on a Windows computer <a class="header-anchor" href="#install-adb-on-a-windows-computer" aria-label="Permalink to &quot;Install ADB on a Windows computer&quot;">​</a></h3><ol><li><p>Download <a href="https://developer.android.com/studio/releases/platform-tools#downloads" target="_blank" rel="noreferrer">Android Debug Bridge</a> on your computer.<br><code>1</code> Open the Downloads folder<br><code>2</code> Open the file you downloaded<br><code>3</code> Select all files<br><code>4</code> Copy them into the <code>5</code> adb folder you created in C:</p><img src="'+l+'"></li><li><p>Run a new command prompt window (<code>Start -&gt; Run - &gt; cmd</code>) with Administrator privileges.<br><img src="'+d+'"></p></li></ol><h3 id="sideload-an-app-with-adb-in-windows" tabindex="-1">Sideload an app with ADB in Windows <a class="header-anchor" href="#sideload-an-app-with-adb-in-windows" aria-label="Permalink to &quot;Sideload an app with ADB in Windows&quot;">​</a></h3><ol><li>Connect your device (watch/phone) with a USB cable to your computer, unlock the screen.</li><li>Enter <code>cd \\adb</code><br><img src="'+s+'"></li><li>Enter <code>adb devices</code><br><img src="'+c+'"></li><li>Look at the device connected and authorize debug, always.<br><img src="'+o+'" style="zoom:75%;"><br><img src="'+a+'" style="zoom:75%;"></li><li>Enter again <code>adb devices</code><br> You should now see your device in the list.<br><img src="'+p+'"></li><li>Copy the file you want to install into the C:\\ADB folder (let&#39;s call it <code>myapplication.apk</code> as an example; if its name contains spaces rename it to something short and simple, like <code>oop.apk</code> or <code>xdrip.apk</code>).</li><li>Enter the command <code>adb install -r myapplication.apk</code> and wait for completion (replace <code>myapplication</code> with the name of your app).</li><li>The app should now be present on your device.</li></ol><h3 id="install-adb-on-a-mac" tabindex="-1">Install ADB on a Mac <a class="header-anchor" href="#install-adb-on-a-mac" aria-label="Permalink to &quot;Install ADB on a Mac&quot;">​</a></h3><ol><li>Download <a href="https://developer.android.com/studio/releases/platform-tools#downloads" target="_blank" rel="noreferrer">Android Debug Bridge</a> on your computer.<br><code>1</code> Open the Downloads folder in Finder<br><code>2</code> Right click the platform tools folder<br><code>3</code> Select New Terminal at Folder</li></ol><img src="'+h+'"><h3 id="sideload-an-app-with-adb-in-ios" tabindex="-1">Sideload an app with ADB in macOS <a class="header-anchor" href="#sideload-an-app-with-adb-in-ios" aria-label="Permalink to &quot;Sideload an app with ADB in macOS {#sideload-an-app-with-adb-in-ios}&quot;">​</a></h3><ol><li><p>Connect your device (watch/phone) with a USB cable to your computer, unlock the screen.</p></li><li><p>Enter <code>./adb devices</code><br><img src="'+m+'"></p></li><li><p>Look at the device connected and authorize debug, always.<br><img src="'+o+'" style="zoom:75%;"><br><img src="'+a+'" style="zoom:75%;"></p></li><li><p>Enter again <code>./adb devices</code><br> You should now see your device in the list.</p></li><li><p>Copy the file you want to install into the platform tools folder (let&#39;s call it <code>myapplication.apk</code> as an example; if its name contains spaces rename it to something short and simple, like <code>oop.apk</code> or <code>xdrip.apk</code>).</p></li><li><p>Enter the command <code>./adb install -r myapplication.apk</code> and wait for completion (replace <code>myapplication</code> with the name of your app).</p></li><li><p>The app should now be present on your device.</p></li></ol><h3 id="install_failed_version_downgrade" tabindex="-1">INSTALL_FAILED_VERSION_DOWNGRADE <a class="header-anchor" href="#install_failed_version_downgrade" aria-label="Permalink to &quot;INSTALL_FAILED_VERSION_DOWNGRADE&quot;">​</a></h3><p>This probably means the app is already present on your device with a more recent version.</p><p>Try to find it and uninstall it.</p><p>If there&#39;s no way to uninstall it, try to sideload with the downgrade switch:</p><p>(Windows) <code>adb install -r -d myapplication.apk</code></p><p>(Mac) <code>./adb install -r -d myapplication.apk</code></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.08.02" target="_blank" rel="noreferrer"><em>Last modified 4/8/2024</em></a></p>',24)])])}const E=u(_,[["render",f]]);export{q as __pageData,E as default};
